// Claude fixes: part 2 shadowed the `store` helper with `const store = await store(...)` in every
// function (TDZ ReferenceError); clearAll used `transaction.done` from the idb library, which does
// not exist on a native IDBTransaction; bulkPut awaited between puts inside one transaction.

const DB_NAME = 'gymtrack';
const DB_VERSION = 1;
let dbPromise = null;

export function uid() {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 10);
}

export function openDb() {
  if (dbPromise) {
    return dbPromise;
  }
  dbPromise = new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onupgradeneeded = function (event) {
      const db = event.target.result;
      if (!db.objectStoreNames.contains('exercises')) {
        const exercisesStore = db.createObjectStore('exercises', { keyPath: 'id' });
        exercisesStore.createIndex('name', 'name', { unique: false });
      }
      if (!db.objectStoreNames.contains('routines')) {
        db.createObjectStore('routines', { keyPath: 'id' });
      }
      if (!db.objectStoreNames.contains('sessions')) {
        const sessionsStore = db.createObjectStore('sessions', { keyPath: 'id' });
        sessionsStore.createIndex('startedAt', 'startedAt', { unique: false });
        sessionsStore.createIndex('routineId', 'routineId', { unique: false });
      }
      if (!db.objectStoreNames.contains('sets')) {
        const setsStore = db.createObjectStore('sets', { keyPath: 'id' });
        setsStore.createIndex('sessionId', 'sessionId', { unique: false });
        setsStore.createIndex('exerciseId', 'exerciseId', { unique: false });
        setsStore.createIndex('at', 'at', { unique: false });
      }
    };
    request.onsuccess = function (event) { resolve(event.target.result); };
    request.onerror = function (event) { reject(event.target.error); };
  });
  return dbPromise;
}

async function storeOf(name, mode) {
  const db = await openDb();
  return db.transaction(name, mode).objectStore(name);
}

function wrap(request) {
  return new Promise((resolve, reject) => {
    request.onsuccess = function (event) { resolve(event.target.result); };
    request.onerror = function (event) { reject(event.target.error); };
  });
}

function done(tx) {
  return new Promise((resolve, reject) => {
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
    tx.onabort = () => reject(tx.error);
  });
}

export async function put(name, value) {
  const st = await storeOf(name, 'readwrite');
  await wrap(st.put(value));
  return value;
}

export async function get(name, id) {
  const st = await storeOf(name, 'readonly');
  return wrap(st.get(id));
}

export async function all(name) {
  const st = await storeOf(name, 'readonly');
  return wrap(st.getAll());
}

export async function del(name, id) {
  const st = await storeOf(name, 'readwrite');
  await wrap(st.delete(id));
}

export async function byIndex(name, indexName, value) {
  const st = await storeOf(name, 'readonly');
  return wrap(st.index(indexName).getAll(value));
}

export async function bulkPut(name, values) {
  if (!Array.isArray(values) || values.length === 0) return [];
  const db = await openDb();
  const tx = db.transaction(name, 'readwrite');
  const st = tx.objectStore(name);
  for (const value of values) st.put(value);
  await done(tx);
  return values;
}

export async function delMany(name, ids) {
  if (!Array.isArray(ids) || ids.length === 0) return;
  const db = await openDb();
  const tx = db.transaction(name, 'readwrite');
  const st = tx.objectStore(name);
  for (const id of ids) st.delete(id);
  await done(tx);
}

export async function clearAll() {
  const db = await openDb();
  const names = ['exercises', 'routines', 'sessions', 'sets'];
  const tx = db.transaction(names, 'readwrite');
  for (const storeName of names) tx.objectStore(storeName).clear();
  await done(tx);
}
